#!/usr/bin/env bash`nset -euo pipefail`n`nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"`nREPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd -P)"`nMANIFEST_PATH="$REPO_ROOT/deploy/manifest.txt"`nHOME_DIR="${HOME:-$(cd ~ && pwd -P)}"`nTIMESTAMP="$(date +%Y%m%d-%H%M%S)"`n`nDRY_RUN=0`nNO_DEPS=1          # safe default: never run sudo to install packages`nINSTALL_DEPS=0     # opt-in with --install-deps`nNON_INTERACTIVE=0`nCONFLICT_ACTION="ask"`ndeclare -a CATEGORIES=()`n`nusage() {`n  cat <<EOF`nUsage: $(basename "$0") [options]`n`nOptions:`n  --repo-root <path>          Override repository root`n  --conflict-action <mode>    ask|replace|merge|keep (default: ask)`n  --category <name>           Filter by category (e.g., skills, agents)`n  --dry-run                   Print actions without changing files`n  --install-deps              Auto-install missing dependencies via sudo (off by default)`n  --no-deps                   Alias for default; never run sudo (kept for compatibility)`n  --non-interactive           Never prompt; with ask-mode defaults to keep`n  -h, --help                  Show help`nEOF`n}`n`nwhile [[ $# -gt 0 ]]; do`n  case "$1" in`n    --repo-root)`n      REPO_ROOT="$2"`n      MANIFEST_PATH="$REPO_ROOT/deploy/manifest.txt"`n      shift 2`n      ;;`n    --conflict-action)`n      CONFLICT_ACTION="$2"`n      shift 2`n      ;;`n    --category)`n      CATEGORIES+=("$2")`n      shift 2`n      ;;`n    --dry-run)`n      DRY_RUN=1`n      shift`n      ;;`n    --install-deps)`n      NO_DEPS=0`n      INSTALL_DEPS=1`n      shift`n      ;;`n    --no-deps)`n      NO_DEPS=1`n      INSTALL_DEPS=0`n      shift`n      ;;`n    --non-interactive)`n      NON_INTERACTIVE=1`n      shift`n      ;;`n    -h|--help)`n      usage`n      exit 0`n      ;;`n    *)`n      echo "Unknown argument: $1" >&2`n      usage`n      exit 1`n      ;;`n  esac`ndone`n`nif [[ ! "$CONFLICT_ACTION" =~ ^(ask|replace|merge|keep)$ ]]; then`n  echo "Invalid --conflict-action: $CONFLICT_ACTION" >&2`n  exit 1`nfi`n`nlog_step() { echo "[*] $*"; }`nlog_warn() { echo "[!] $*" >&2; }`n`nrun_cmd() {`n  local desc="$1"`n  shift`n  if [[ $DRY_RUN -eq 1 ]]; then`n    echo "[DRY] $desc :: $*"`n  else`n    "$@"`n  fi`n}`n`ncommand_exists() {`n  command -v "$1" >/dev/null 2>&1`n}`n`nabspath() {`n  local p="$1"`n  local dir`n  dir="$(cd "$(dirname "$p")" && pwd -P)"`n  echo "$dir/$(basename "$p")"`n}`n`nensure_parent_dir() {`n  local target="$1"`n  local parent`n  parent="$(dirname "$target")"`n  run_cmd "Create directory: $parent" mkdir -p "$parent"`n}`n`nbackup_existing() {`n  local target="$1"`n  local backup="${target}.backup-${TIMESTAMP}"`n  run_cmd "Backup: $target -> $backup" cp -a "$target" "$backup"`n}`n`nshow_diff() {`n  local source="$1"`n  local target="$2"`n  echo`n  echo "--- DIFF: $target <-> $source"`n  if command_exists git; then`n    git --no-pager diff --no-index -- "$target" "$source" || true`n  elif command_exists diff; then`n    diff -u "$target" "$source" || true`n  else`n    echo "(diff tool not found)"`n  fi`n}`n`nwrite_merged_conflict_file() {`n  local source="$1"`n  local target="$2"`n  local existing_text=""`n  if [[ -f "$target" ]]; then`n    existing_text="$(cat "$target")"`n  fi`n  local source_text`n  source_text="$(cat "$source")"`n  if [[ $DRY_RUN -eq 1 ]]; then`n    echo "[DRY] Write merged conflict file: $target"`n    return`n  fi`n  cat > "$target" <<EOF`n<<<<<<< LOCAL ($target)`n$existing_text`n=======`n$source_text`n>>>>>>> REPOSITORY ($source)`nEOF`n}`n`nresolve_link_target() {`n  local target="$1"`n  local link`n  link="$(readlink "$target")"`n  if [[ "$link" = /* ]]; then`n    echo "$link"`n  else`n    abspath "$(dirname "$target")/$link"`n  fi`n}`n`nis_same_symlink() {`n  local source="$1"`n  local target="$2"`n  if [[ ! -L "$target" ]]; then`n    return 1`n  fi`n  local src_abs`n  src_abs="$(abspath "$source")"`n  local link_abs`n  link_abs="$(resolve_link_target "$target")"`n  [[ "$src_abs" == "$link_abs" ]]`n}`n`ncreate_link() {`n  local source="$1"`n  local target="$2"`n  local src_abs`n  src_abs="$(abspath "$source")"`n  ensure_parent_dir "$target"`n  if [[ $DRY_RUN -eq 1 ]]; then`n    echo "[DRY] Link: $target -> $src_abs"`n    return`n  fi`n  rm -rf "$target"`n  ln -s "$src_abs" "$target"`n}`n`nselect_action() {`n  local source="$1"`n  local target="$2"`n  if [[ "$CONFLICT_ACTION" != "ask" ]]; then`n    echo "$CONFLICT_ACTION"`n    return`n  fi`n  # Fall back to keep when not interactive (no TTY or --non-interactive flag)`n  if [[ $NON_INTERACTIVE -eq 1 ]] || [[ ! -t 0 ]]; then`n    echo "keep"`n    return`n  fi`n`n  show_diff "$source" "$target"`n  echo`n  echo "Target exists: $target"`n  echo "[R]eplace with link to repo"`n  echo "[M]erge into local file (conflict markers, no link)"`n  echo "[K]eep local file (no link)"`n  while true; do`n    if ! read -r -p "Choose action [R/M/K]: " answer; then`n      # EOF on stdin — treat as non-interactive, keep local`n      echo "keep"`n      return`n    fi`n    answer="$(echo "$answer" | tr '[:upper:]' '[:lower:]')"`n    case "$answer" in`n      r) echo "replace"; return ;;`n      m) echo "merge"; return ;;`n      k) echo "keep"; return ;;`n      *) log_warn "Invalid choice. Enter R, M, or K." ;;`n    esac`n  done`n}`n`ndeploy_file() {`n  local source="$1"`n  local target="$2"`n  if [[ ! -f "$source" ]]; then`n    log_warn "Skip missing source file: $source"`n    return`n  fi`n`n  if [[ ! -e "$target" && ! -L "$target" ]]; then`n    create_link "$source" "$target"`n    return`n  fi`n`n  if is_same_symlink "$source" "$target"; then`n    echo "[=] Already linked: $target"`n    return`n  fi`n`n  local action`n  action="$(select_action "$source" "$target")"`n  case "$action" in`n    replace)`n      backup_existing "$target"`n      create_link "$source" "$target"`n      ;;`n    merge)`n      backup_existing "$target"`n      write_merged_conflict_file "$source" "$target"`n      ;;`n    keep)`n      echo "[=] Keep local: $target"`n      ;;`n    *)`n      log_warn "Unsupported action: $action"`n      ;;`n  esac`n}`n`ndeploy_entry() {`n  local source_rel="$1"`n  local target_rel="$2"`n  local source_path="$REPO_ROOT/$source_rel"`n  local target_path="$HOME_DIR/$target_rel"`n`n  if [[ ! -e "$source_path" ]]; then`n    log_warn "Skip (source missing): $source_rel"`n    return`n  fi`n`n  if [[ -d "$source_path" ]]; then`n    log_step "Deploy directory: $source_rel -> $target_rel"`n    while IFS= read -r src_file; do`n      local rel="${src_file#"$source_path"/}"`n      deploy_file "$src_file" "$target_path/$rel"`n    done < <(find "$source_path" -type f)`n  else`n    log_step "Deploy file: $source_rel -> $target_rel"`n    deploy_file "$source_path" "$target_path"`n  fi`n}`n`nensure_dependency() {`n  local cmd="$1"`n  local package_name="$2"`n  if command_exists "$cmd"; then`n    return 0`n  fi`n  if [[ $INSTALL_DEPS -eq 0 ]]; then`n    log_warn "$cmd not found — skipping (pass --install-deps to auto-install via sudo)."`n    return 1`n  fi`n`n  # Verify sudo is available and usable before running privileged commands`n  if ! command_exists sudo; then`n    log_warn "$cmd not found and sudo is not available. Install $package_name manually."`n    return 1`n  fi`n  if ! sudo -n true 2>/dev/null; then`n    log_warn "$cmd not found but sudo requires a password. Install $package_name manually or run with sudo."`n    return 1`n  fi`n`n  if command_exists brew; then`n    run_cmd "Install dependency: brew install $package_name" brew install "$package_name"`n  elif command_exists apt-get; then`n    run_cmd "Install dependency: apt-get install $package_name" sudo apt-get install -y "$package_name"`n  elif command_exists dnf; then`n    run_cmd "Install dependency: dnf install $package_name" sudo dnf install -y "$package_name"`n  elif command_exists yum; then`n    run_cmd "Install dependency: yum install $package_name" sudo yum install -y "$package_name"`n  elif command_exists pacman; then`n    run_cmd "Install dependency: pacman -S $package_name" sudo pacman -Sy --noconfirm "$package_name"`n  elif command_exists zypper; then`n    run_cmd "Install dependency: zypper install $package_name" sudo zypper install -y "$package_name"`n  else`n    log_warn "$cmd missing and no supported package manager detected."`n    return 1`n  fi`n  command_exists "$cmd"`n}`n`nensure_git_config() {`n  if ! command_exists git; then`n    return`n  fi`n`n  local name email`n  name="$(git config --global --get user.name || true)"`n  email="$(git config --global --get user.email || true)"`n`n  if [[ -z "$name" ]]; then`n    if [[ $NON_INTERACTIVE -eq 1 ]]; then`n      log_warn "git user.name not configured. Set it manually."`n    else`n      read -r -p "git user.name is empty. Enter your name (or empty to skip): " name_input`n      if [[ -n "${name_input:-}" ]]; then`n        run_cmd "Set git user.name" git config --global user.name "$name_input"`n      fi`n    fi`n  fi`n`n  if [[ -z "$email" ]]; then`n    if [[ $NON_INTERACTIVE -eq 1 ]]; then`n      log_warn "git user.email not configured. Set it manually."`n    else`n      read -r -p "git user.email is empty. Enter your email (or empty to skip): " email_input`n      if [[ -n "${email_input:-}" ]]; then`n        run_cmd "Set git user.email" git config --global user.email "$email_input"`n      fi`n    fi`n  fi`n`n  run_cmd "Set git core.excludesfile" git config --global core.excludesfile "$HOME_DIR/.gitignore_global"`n  run_cmd "Set git core.hooksPath" git config --global core.hooksPath "$HOME_DIR/.githooks"`n}`n`nensure_commit_policy() {`n  if ! command_exists git; then`n    return`n  fi`n  if [[ -f "$REPO_ROOT/.ai-agent-config-repo" ]]; then`n    run_cmd "Marking repo as canonical AI config repo" git config ai-agent.allow-config-commits true`n  fi`n}`n`nensure_codex_local_trust() {`n  local local_config="$REPO_ROOT/.codex/config.toml"`n  if [[ -f "$local_config" ]]; then`n    if ! grep -q "trust_repository[[:space:]]*=[[:space:]]*true" "$local_config"; then`n      run_cmd "Trusting repository in local Codex config" echo "trust_repository = true" >> "$local_config"`n    fi`n  fi`n}`n`nensure_codex_global_trust() {`n  local global_config="$HOME_DIR/.codex/config.toml"`n  # Convert POSIX path to Windows extended-length path (\\?\C:\...)`n  local win_path`n  if command_exists cygpath; then`n    win_path="$(cygpath -w "$REPO_ROOT")"`n  else`n    win_path="$REPO_ROOT"`n  fi`n  # Prepend \\?\ prefix if this is a Windows absolute path`n  if [[ "$win_path" =~ ^[A-Za-z]:\\ ]]; then`n    win_path="\\\\?\\$win_path"`n  fi`n`n  local toml_header="[projects.'$win_path']"`n  local trust_line='trust_level = "trusted"'`n`n  if [[ ! -f "$global_config" ]]; then`n    run_cmd "Initialize Codex global trust" mkdir -p "$(dirname "$global_config")"`n    if [[ $DRY_RUN -eq 0 ]]; then`n      printf 'approval_policy = "never"\nsandbox_mode = "workspace-write"\n\n%s\n%s\n' "$toml_header" "$trust_line" > "$global_config"`n    else`n      echo "[DRY] Write $global_config with trust for $win_path"`n    fi`n    return`n  fi`n`n  if ! grep -Fq "$win_path" "$global_config"; then`n    if [[ $DRY_RUN -eq 0 ]]; then`n      printf '\n%s\n%s\n' "$toml_header" "$trust_line" >> "$global_config"`n    else`n      echo "[DRY] Append trust for $win_path to $global_config"`n    fi`n  fi`n}`n`ninvoke_auto_backup() {`n  local backup_script="$SCRIPT_DIR/backup-user-config.sh"`n  if [[ ! -f "$backup_script" ]]; then`n    echo "Backup script not found: $backup_script" >&2`n    exit 1`n  fi`n`n  log_step "Creating automatic pre-install backup"`n  local cmd=(bash "$backup_script" --repo-root "$REPO_ROOT" --backup-name "install-$TIMESTAMP")`n  if [[ $DRY_RUN -eq 1 ]]; then`n    cmd+=(--dry-run)`n  fi`n  "${cmd[@]}"`n}`n`nif [[ ! -f "$MANIFEST_PATH" ]]; then`n  echo "Manifest not found: $MANIFEST_PATH" >&2`n  exit 1`nfi`n`nlog_step "Repo root: $REPO_ROOT"`ninvoke_auto_backup`n`n# ---------------------------------------------------------------------------`n# Build step: generate tier files and adapters into out/ before deploy.`n# ---------------------------------------------------------------------------`nlog_step "Building tier files and adapters into out/"`nEXTRACT_SCRIPT="$REPO_ROOT/scripts/extract-agents-tier.sh"`nif [[ -f "$EXTRACT_SCRIPT" ]]; then`n  bash "$EXTRACT_SCRIPT" --out "$REPO_ROOT/out" >/dev/null 2>&1 || true`nfi`n`nlog_step "Checking dependencies"`nensure_dependency git git || true`nensure_dependency gitleaks gitleaks || true`n`nentry_count=0`nCURRENT_CATEGORY="default"`nwhile IFS='|' read -r source_rel target_rel; do`n  line="${source_rel}${target_rel}"`n  if [[ -z "${line// }" ]]; then`n    continue`n  fi`n  `n  if [[ "${source_rel#"${source_rel%%[![:space:]]*}"}" == \#* ]]; then`n    if [[ "$source_rel" =~ @category[[:space:]]+([^[:space:]]+) ]]; then`n      CURRENT_CATEGORY="${BASH_REMATCH[1]}"`n    fi`n    continue`n  fi`n`n  # Filter by category if requested`n  if [[ ${#CATEGORIES[@]} -gt 0 ]]; then`n    match=0`n    for cat in "${CATEGORIES[@]}"; do`n      if [[ "$cat" == "$CURRENT_CATEGORY" ]]; then`n        match=1`n        break`n      fi`n    done`n    [[ $match -eq 0 ]] && continue`n  fi`n`n  source_rel="$(echo "$source_rel" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"`n  target_rel="$(echo "$target_rel" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"`n  [[ -z "$source_rel" || -z "$target_rel" ]] && continue`n  entry_count=$((entry_count + 1))`n  deploy_entry "$source_rel" "$target_rel"`ndone < "$MANIFEST_PATH"`n`nlog_step "Manifest entries: $entry_count"`nensure_git_config`nensure_commit_policy`nensure_codex_local_trust`nensure_codex_global_trust`n`nif [[ -f "$HOME_DIR/.githooks/pre-commit" && $DRY_RUN -eq 0 ]]; then`n  chmod +x "$HOME_DIR/.githooks/pre-commit" || true`nfi`n`nlog_step "Done."`n